import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 37 · Christmas tips: homemade gifts from the kitchen (Google Trends 3/11: homemade christmas gifts, christmas treat recipes rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, the best Christmas present I ever got cost about forty cents. It was a jar of my mother's apple butter, with a square of red calico tied on the lid with string. I was twenty, newly married, living in a tiny apartment, and homesick. I opened that jar and the whole kitchen smelled like Elm Street. I cried into my toast.""",
   "jar apple butter calico lid", "FORTY CENTS")
sc("""So tonight I'm giving you nine homemade Christmas gifts from the kitchen that people actually love, all for under five dollars each, and how to wrap them so they look like they came from a fancy shop. And stay with me, because the last one is the gift people keep for years, and it isn't even food.""",
   "homemade Christmas gift jars ribbon", "UNDER FIVE DOLLARS")

ch("Why kitchen gifts")
sc("""When I was a girl in the fifties, nobody on our street had money for store presents for everybody. So the women gave from the kitchen. Mrs. Kowalski gave poppy seed bread. Mrs. MacLeod gave shortbread. My mother gave apple butter and fudge. And every one of those gifts was remembered longer than any sweater from the department store.""",
   "1950s women kitchen baking Christmas", "GIVEN FROM THE KITCHEN")
sc("""A store gift says, I thought of you at the mall. A kitchen gift says, I thought of you for a whole afternoon. That's the difference, honey. And it's the one gift nobody can return. In a minute I'll tell you the one rule for every kitchen gift, the one that makes a two-dollar jar look like twenty.""",
   "hands tying ribbon on jar", "A WHOLE AFTERNOON")

ch("1. Spiced nuts")
sc("""Number one. Sugared spiced pecans. Whisk one egg white with a spoon of water until it's foamy. Toss in a pound of pecan halves. Then toss them with a cup of sugar, a teaspoon of cinnamon, a teaspoon of salt, and a pinch of cayenne. Spread them on a baking sheet and bake at two hundred fifty for an hour, stirring every fifteen minutes.""",
   "sugared spiced pecans baking sheet", "SUGARED PECANS")
sc("""They come out crackly and sweet and a little bit hot at the end. A pound of pecans fills four little jars. My husband used to hide one jar in the garage for himself, behind the paint cans, and pretend I'd miscounted. I never miscounted, honey. I just let him think I did.""",
   "jar of candied pecans gift", "BEHIND THE PAINT CANS")

ch("2. Cookie mix in a jar")
sc("""Number two. Cookie mix in a jar. In a quart mason jar, layer the dry ingredients for your favorite cookie. Flour with the baking soda and salt on the bottom, then brown sugar, packed down, then white sugar, then oats, then chocolate chips on top. The stripes look beautiful through the glass. Then tie a card on the lid with what to add and how long to bake.""",
   "layered cookie mix mason jar", "STRIPES IN A JAR")
sc("""Pack every layer down hard with the bottom of a small glass, so they stay neat and don't mix. That's the mistake most people make. And write the card by hand, honey. Add one stick of butter, one egg, one teaspoon of vanilla. Bake at three seventy-five for ten minutes. The young mothers at my church love these, because their children can make them.""",
   "handwritten recipe tag jar", "PACK EVERY LAYER")

ch("3. Fudge and bark")
sc("""Number three. Fudge or chocolate bark, cut in squares and stacked in a little tin or a paper box with wax paper between the layers. A batch of fudge costs about six dollars and fills five boxes. Bark is even easier. Melt chocolate, spread it thin, and scatter crushed candy canes, nuts or dried cranberries on top. I have whole videos on both on my channel.""",
   "Christmas fudge squares tin wax paper", "FIVE BOXES")

sc("""And a word about fudge as a gift, honey. Cut it small, one-inch squares, because fudge is rich and people eat it a little at a time. Put each square in a tiny paper candy cup, the kind for muffins but small. Twelve squares in a box, each in its own paper cup, looks like something from a candy shop on Main Street. My mother learned that from the lady at the five and dime.""",
   "fudge squares paper candy cups box", "LIKE A CANDY SHOP")

ch("4. Flavored sugar and salt")
sc("""Number four, and this is the cheapest one on the list. Flavored sugar. Put two cups of sugar in a jar with a split vanilla bean, or the peel of an orange, or a few cinnamon sticks, and let it sit two weeks. Or mix coarse salt with dried rosemary and lemon zest for cooking. It costs about a dollar a jar, and it looks like something from a gourmet shop.""",
   "vanilla sugar jar cinnamon sticks", "ABOUT A DOLLAR")
sc("""If this is helping you, honey, tap the like button for me. It helps Grandma more than you know. And now the one rule I promised you, for every single gift on this list. Make the jar beautiful, and keep the label simple. A clean jar, a square of fabric or brown paper on the lid, real string or ribbon, and a handwritten tag. That's what makes it look like twenty dollars.""",
   "brown paper kraft label twine jar", "MAKE THE JAR BEAUTIFUL")

ch("5. Hot cocoa mix")
sc("""Number five. Homemade hot cocoa mix. Mix two cups of powdered milk, one cup of powdered sugar, three quarters of a cup of good cocoa powder, and a pinch of salt. Put it in a jar, with a little bag of mini marshmallows on top. Three big spoons in a mug of hot water or milk. Add a candy cane tied to the side, and you have a gift every child in the family wants.""",
   "hot cocoa mix jar marshmallows", "EVERY CHILD WANTS ONE")
sc("""Sift the cocoa, sweetheart, that's the secret. Unsifted cocoa makes lumps that float on top of the mug like little rocks, and nobody likes that. Sift it with the sugar right into the bowl, then stir in the milk powder. It'll dissolve smooth every time. My grandson calls it Grandma's magic dust.""",
   "sifting cocoa powder bowl", "GRANDMA'S MAGIC DUST")

ch("6. Quick bread")
sc("""Number six. A loaf of quick bread, wrapped in parchment and tied with string. Pumpkin bread, banana bread, or cranberry orange. One batch makes four little loaves in small foil pans, and they freeze for three months. So I bake them the first week of December and pull one out every time somebody surprises me with a visit.""",
   "mini loaves pumpkin bread parchment", "FOUR LITTLE LOAVES")
sc("""So far, spiced nuts, cookie mix in a jar, fudge and bark, flavored sugar, cocoa mix, and quick bread. And here's a tip for the bread. Let the loaves cool completely, all the way, before you wrap them. Wrap them warm, and the steam makes the tops wet and sticky by morning. Cool bread, then parchment, then string, then a sprig of pine tucked in the bow.""",
   "wrapped loaf twine pine sprig", "COOL IT COMPLETELY")

ch("7. Jam and apple butter")
sc("""Number seven. The one my mother made. Apple butter in the slow cooker. Peel and slice six pounds of apples, add a cup of brown sugar, two teaspoons of cinnamon, a little nutmeg and cloves, and cook it on low for ten hours, until it's dark brown and thick. Blend it smooth, and spoon it into clean jars. It keeps three weeks in the icebox.""",
   "apple butter slow cooker spoon", "TEN HOURS ON LOW")
sc("""And you don't have to know how to can, honey. Just tell people to keep it in the icebox and use it within three weeks, or freeze it. Nobody has ever let a jar of apple butter last three weeks in my family. My brother Danny eats his with a spoon, standing at the counter.""",
   "jar of apple butter toast", "WITH A SPOON")

ch("8. A baking basket")
sc("""Number eight. For the young cook in the family. A basket, or a big mixing bowl, filled with a wooden spoon, a good spatula, a set of measuring cups, a bag of chocolate chips, and your best cookie recipe written on a card. Put a bow on the bowl. It costs a little more, maybe fifteen dollars, but it starts somebody cooking for the rest of their life.""",
   "mixing bowl gift wooden spoon recipe", "A BOWL WITH A BOW")

sc("""And put a little something extra in the basket. A dish towel with a Christmas print, or an apron. A pot holder. For my granddaughter's first apartment, I tucked in a little card with my phone number and the words, call me when it doesn't work. She called me eleven times that first winter. Best gift I ever gave, because I got eleven phone calls.""",
   "Christmas dish towel apron basket", "CALL ME")

ch("9. The gift they keep")
sc("""And number nine, the gift people keep for years, the one I told you about at the start. It isn't food at all. It's the recipe itself. Write your family's best recipe on a card, in your own handwriting, with a little note. Who taught it to you, and one memory of eating it. Then tuck it in with whatever you're giving.""",
   "handwritten recipe card old", "IT ISN'T FOOD")
sc("""My mother's apple butter is long gone, sweetheart. But I still have the card she tied to that jar in nineteen sixty-four. Her handwriting, in blue ink. To Ruthie, so you're never homesick at Christmas. Love, Mama. It's in my recipe box, and it's the most valuable thing I own. Your handwriting is a gift nobody else can give.""",
   "old recipe box cards handwriting", "NEVER HOMESICK")

ch("Wrapping and giving")
sc("""A few last tips. Buy your jars after Christmas, on sale, for next year. Save the pretty tins people give you. Brown paper lunch bags, folded over and punched with two holes for ribbon, make perfect bags for cookies. And always label anything with nuts. Somebody at the church party always has an allergy, and you want them to be safe.""",
   "brown paper bags ribbon cookies", "LABEL THE NUTS")

ch("Grandma's kitchen")
sc("""So one more time. Spiced pecans. Cookie mix in a jar. Fudge and bark. Flavored sugar. Cocoa mix. Quick bread. Apple butter. A baking bowl for the young cook. And your own recipe, in your own handwriting. Make the jar beautiful, keep the label simple, and give it with a hug. That's how my mother did Christmas on almost nothing.""",
   "table of homemade Christmas gifts", "WITH A HUG")
sc("""Tell me in the comments, sweetheart. What's the best homemade gift anybody ever gave you? I read every one. The whole playlist of Grandma's Christmas tips is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas kitchen window evening", "THE BEST HOMEMADE GIFT?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma37", "9 Homemade Christmas Gifts EVERYONE Loves (Under $5 Each)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Kitchen gifts as a Christmas tradition in mid-century American neighborhoods.",
      "Recipes as written by Grandma Ruth: spiced pecans (1 egg white, 1 lb pecans, 1 cup sugar, cinnamon, salt, cayenne; 250 F for 1 hour); cocoa mix (2 cups powdered milk, 1 cup powdered sugar, 3/4 cup cocoa); slow cooker apple butter (6 lb apples, 1 cup brown sugar, spices, 10 hours on low)."],
     "christmas with tips", minutes=(10, 14.5), voice="en_US-lessac-high")
